#!/usr/bin/env python3
"""Generate WorkerScript from the parser used by the deterministic tests."""
from pathlib import Path
root = Path(__file__).resolve().parents[1] / 'qml/decodium/components'
parser = (root / 'DxCalendarParser.js').read_text(encoding='utf-8')
assert parser.startswith('.pragma library\n')
handler = '''\nWorkerScript.onMessage = function(message) {\n    if (message.kind === "parse") {\n        WorkerScript.sendMessage({kind: "parse", serial: message.serial,\n                                  entries: parse(message.text),\n                                  text: message.text, updated: message.updated,\n                                  fromCache: message.fromCache});\n    } else if (message.kind === "filter") {\n        var mode = message.selection === "current" ? "all" : message.selection;\n        var rows = filter(message.entries, message.query, mode, message.today);\n        if (message.selection === "current")\n            rows = rows.filter(function(e) { return e.end >= message.today; });\n        WorkerScript.sendMessage({kind: "filter", serial: message.serial, rows: rows});\n    }\n};\n'''
(root / 'DxCalendarWorker.js').write_text('// Generated by scripts/update_dxcalendar_worker.py\n' + parser.removeprefix('.pragma library\n') + handler, encoding='utf-8')
